do $test$
declare owner uuid; workspace uuid; learner uuid:=gen_random_uuid(); course uuid:=gen_random_uuid(); version uuid:=gen_random_uuid(); module uuid:=gen_random_uuid(); lesson uuid:=gen_random_uuid(); entitlement uuid:=gen_random_uuid(); enrollment uuid:=gen_random_uuid(); assessment uuid:=gen_random_uuid(); quiz uuid:=gen_random_uuid(); question uuid:=gen_random_uuid(); good uuid:=gen_random_uuid(); bad uuid:=gen_random_uuid(); attempt uuid; again uuid; denied boolean;
begin
 begin
  select user_id into owner from public.platform_founder limit 1;
  select id into workspace from public.workspaces where owner_id=owner limit 1;
  insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values(learner,'rollback-'||learner::text||'@example.invalid','{"full_name":"Rollback Learner"}',now());
  insert into public.courses(id,owning_workspace_id,owner_id,title,slug,short_description) values(course,workspace,owner,'Rollback learning','rollback-'||course::text,'Temporary test');
  insert into public.course_versions(id,course_id,version_number,created_by) values(version,course,1,owner);
  insert into public.course_modules(id,course_id,version_id,title,display_order) values(module,course,version,'Module',1);
  insert into public.course_lessons(id,course_id,module_id,version_id,title,slug,lesson_type,display_order) values(lesson,course,module,version,'Class','test','video',1);
  insert into public.entitlements(id,beneficiary_user_id,course_id,course_version_id,source_type) values(entitlement,learner,course,version,'test');
  insert into public.enrollments(id,learner_id,course_id,course_version_id,entitlement_id,source) values(enrollment,learner,course,version,entitlement,'test');
  insert into public.assessments(id,course_id,module_id,lesson_id,assessment_type,title,required) values(assessment,course,module,lesson,'quiz','Check',true);
  insert into public.quizzes(id,assessment_id,passing_score,attempts_allowed,show_correct_answers) values(quiz,assessment,70,2,true);
  insert into public.quiz_questions(id,quiz_id,prompt,question_type,display_order) values(question,quiz,'Which?','single_choice',1);
  insert into public.quiz_question_options(id,question_id,option_text,is_correct,display_order) values(good,question,'Correct',true,1),(bad,question,'Wrong',false,2);
  update public.course_versions set status='published' where id=version;
  if (select status from public.assessments where id=assessment)<>'active' then raise exception 'Publish did not activate checks'; end if;
  if public.learning_refresh_completion(enrollment,learner) then raise exception 'Incomplete learning completed'; end if;
  attempt:=public.learning_start_check(enrollment,quiz,learner);again:=public.learning_start_check(enrollment,quiz,learner);
  if attempt<>again then raise exception 'Duplicate attempt'; end if;
  denied:=false;begin perform public.learning_submit_check(attempt,owner,jsonb_build_object(question,good)); exception when raise_exception then denied:=true;end;
  if not denied then raise exception 'Foreign learner scored'; end if;
  denied:=false;begin perform public.learning_submit_check(attempt,learner,'{}');exception when raise_exception then denied:=true;end;
  if not denied then raise exception 'Missing answer accepted';end if;
  perform public.learning_save_check(attempt,learner,jsonb_build_object(question,bad));
  perform public.learning_submit_check(attempt,learner,jsonb_build_object(question,bad));
  if (select passed from public.quiz_attempts where id=attempt) then raise exception 'Wrong answer passed';end if;
  perform public.learning_submit_check(attempt,learner,jsonb_build_object(question,good));
  if (select passed from public.quiz_attempts where id=attempt) then raise exception 'Submitted attempt changed';end if;
  again:=public.learning_start_check(enrollment,quiz,learner);
  perform public.learning_submit_check(again,learner,jsonb_build_object(question,good));
  denied:=false;begin perform public.learning_start_check(enrollment,quiz,learner);exception when raise_exception then denied:=true;end;
  if not denied then raise exception 'Attempt limit ignored';end if;
  if public.learning_refresh_completion(enrollment,learner) then raise exception 'Unwatched class completed';end if;
  insert into public.lesson_progress(enrollment_id,lesson_id,status,progress_percentage) values(enrollment,lesson,'completed',100);
  if not public.learning_refresh_completion(enrollment,learner) then raise exception 'Valid completion denied';end if;
  denied:=false;begin perform public.issue_certificate_for_enrollment(enrollment,learner);exception when raise_exception then denied:=true;end;
  if not denied then raise exception 'Unapproved certificate issued';end if;
  insert into public.certificate_templates(name,template,status) values('Rollback certificate',jsonb_build_object('course_id',course,'issuance_enabled',true,'specimen_only',false,'issuer','Rollback Academy'),'active');
  again:=public.issue_certificate_for_enrollment(enrollment,learner);
  if again is null or public.issue_certificate_for_enrollment(enrollment,learner)<>again then raise exception 'Certificate issuance not idempotent';end if;
  if has_function_privilege('authenticated','public.learning_submit_check(uuid,uuid,jsonb)','execute') or has_function_privilege('authenticated','public.issue_certificate_for_enrollment(uuid,uuid)','execute') or has_column_privilege('authenticated','public.quiz_attempts','question_snapshot','select') then raise exception 'Browser can score or read snapshot';end if;
  update public.entitlements set status='revoked' where id=entitlement;
  denied:=false;begin perform public.learning_check_access(enrollment,learner);exception when raise_exception then denied:=true;end;
  if not denied then raise exception 'Revoked access accepted';end if;
  raise exception using errcode='Z0001',message='Rollback fixtures';
 exception when sqlstate 'Z0001' then raise notice 'PASS: published checks, attempt idempotency, wrong answers, limits, foreign access, completion, certificate gating, privilege restrictions, revocation. All fixtures rolled back.';
 end;
end $test$;
